function fakeHermes(
  home: string,
360→  listOut = "[active] night-pass\n",
  opts: { failMcp?: boolean } = {},
): { bin: string; log: string } {
  const bin = mkdtempSync(join(tmpdir(), "dora-hermes-bin-"));
